# =============================================================================
# Data Processing & Vectorization Configuration
# =============================================================================
# Target Classes
CLASSES = ["EAP", "HPL", "MWS"]

# TF-IDF Vectorizer settings
# Word n-grams: Unigrams and Bigrams to capture specific words and short phrases
