# Maximum number of iterations for the solver (Training steps)
MAX_ITER = 1000

# Tolerance for stopping criteria
TOL = 1e-4

# =============================================================================
# Runtime & Reproducibility
# =============================================================================
RANDOM_STATE = 42

# Debugging configuration
# Use these to control dataset size during development/debugging
DEBUG = False
DEBUG_SAMPLE_SIZE = 1000

